sys_variable_value.value:
(function execute(inputs, outputs) {
    var id = inputs.saldo.sys_id ? String(inputs.saldo.sys_id) : String(inputs.saldo);

    var gr = new GlideRecord('x_1863045_hr_sel_1_saldo_de_ferias');
    if (!gr.get(id)) {
        gs.warn('Descontar Saldo: registro de saldo não encontrado.');
        return;
    }

    var atual = parseInt(gr.getValue('dias_disponiveis'), 10);
    var usar = parseInt(inputs.dias, 10);

    if (isNaN(usar) || usar > atual) {
        gs.warn('Descontar Saldo: desconto ignorado (dias=' + inputs.dias + ', saldo=' + atual + ').');
        return;
    }

    gr.setValue('dias_disponiveis', atual - usar);
    gr.update();
})(inputs, outputs);

